WITH filtered_accounts AS (SELECT * FROM accounts WHERE account_type NOT IN ('SAVINGS', 'CREDIT') AND opened_date BETWEEN '2023-04-01' AND '2025-01-12'), opened_quarter_summary AS (SELECT QUARTER(opened_date) AS opened_quarter, ROUND(AVG(balance), 2) AS avg_balance FROM filtered_accounts GROUP BY QUARTER(opened_date)) SELECT opened_quarter, avg_balance FROM opened_quarter_summary ORDER BY avg_balance DESC;
